def envy (v : Valuation Agent Item) (A : Allocation Agent Item)
    (i j : Agent) : ℝ :=
  max 0 (v.value i (A j) - v.value i (A i))

def envyBoundedBy (v : Valuation Agent Item) (A : Allocation Agent Item)
    (alpha : ℝ) : Prop :=
  ∀ i j, envy v A i j ≤ alpha
